use super::*;
fn map(rows: &[(&str,&str)]) -> HeaderMap { let mut h=HeaderMap::new();for (k,v)in rows{h.insert(reqwest::header::HeaderName::from_bytes(k.as_bytes()).unwrap(),v.parse().unwrap());}h }
fn repr() -> Representation {Representation{etag:"\"version-a\"".into(),length:1000,version:BTreeMap::new()}}
fn good_headers() -> HeaderMap {map(&[("etag","\"version-a\""),("content-length","10"),("content-range","bytes 100-109/1000")])}
#[test]fn opaque_strong_etag_is_required(){assert!(strong_etag("\"\""));assert!(strong_etag("\"opaque\""));for s in ["W/\"weak\"","unquoted","\"bad\"interior\"","\"space here\"",""]{assert!(!strong_etag(s));}}
#[test]fn representation_requires_unique_strong_identity(){assert!(representation(&map(&[("etag","\"v\""),("content-length","1000")])).is_ok());assert!(representation(&map(&[("etag","W/\"v\""),("content-length","1000")])).is_err());let mut h=good_headers();h.append("etag","\"other\"".parse().unwrap());assert!(representation(&h).is_err());}
#[test]fn missing_length_is_not_replaced_with_chunked_transfer(){assert!(representation(&map(&[("etag","\"v\"")])).is_err());assert!(representation(&map(&[("etag","\"v\""),("content-length","0")])).is_err());}
#[test]fn range_must_be_exact_not_merely_successful(){assert!(range_headers(&good_headers(),&repr(),100,10).is_ok());for value in ["bytes 99-108/1000","bytes 100-110/1000","bytes 100-109/*","bytes 100-109/1001"]{let mut h=good_headers();h.insert("content-range",value.parse().unwrap());assert!(range_headers(&h,&repr(),100,10).is_err());}}
#[test]fn changed_etag_and_version_header_reject(){let mut h=good_headers();h.insert("etag","\"different\"".parse().unwrap());assert!(range_headers(&h,&repr(),100,10).is_err());let mut p=repr();p.version.insert("x-amz-version-id".into(),"old".into());assert!(range_headers(&good_headers(),&p,100,10).is_err());}
#[test]fn appearing_and_duplicated_version_headers_reject(){let mut h=good_headers();h.insert("x-goog-generation","123".parse().unwrap());assert!(range_headers(&h,&repr(),100,10).is_err());let mut p=repr();p.version.insert("x-goog-generation".into(),"123".into());assert!(range_headers(&h,&p,100,10).is_ok());h.append("x-goog-generation","123".parse().unwrap());assert!(range_headers(&h,&p,100,10).is_err());}
#[test]fn encoded_or_transfer_encoded_body_is_never_source_bytes(){for (k,v)in [("content-encoding","gzip"),("content-encoding","zstd"),("transfer-encoding","chunked")]{let mut h=good_headers();h.insert(reqwest::header::HeaderName::from_bytes(k.as_bytes()).unwrap(),v.parse().unwrap());assert!(range_headers(&h,&repr(),100,10).is_err());}}
#[test]fn zero_overflow_and_outside_ranges_reject(){assert!(range_headers(&good_headers(),&repr(),100,0).is_err());assert!(range_headers(&good_headers(),&repr(),u64::MAX,2).is_err());assert!(range_headers(&good_headers(),&repr(),995,10).is_err());}
#[test]fn raw_index_uses_exact_deterministic_record(){let mut b=vec![0;INDEX_BYTES];b[RECORD..RECORD+8].copy_from_slice(&1234u64.to_le_bytes());b[RECORD+8..RECORD+12].copy_from_slice(&99u32.to_le_bytes());assert_eq!(target_range(&b,5000,40).unwrap(),(1234,99));}
#[test]fn missing_index_record_cannot_skip_to_later_slot(){assert!(target_range(&vec![0;INDEX_BYTES],5000,40).is_err());assert!(target_range(&vec![0;INDEX_BYTES-1],5000,40).is_err());}
#[test]fn raw_index_range_bound_covers_combined_header(){let mut b=vec![0;INDEX_BYTES];b[RECORD..RECORD+8].copy_from_slice(&100u64.to_le_bytes());b[RECORD+8..RECORD+12].copy_from_slice(&(MAX_INPUT as u32).to_le_bytes());assert!(target_range(&b,u64::MAX,40).is_err());b[RECORD+8..RECORD+12].copy_from_slice(&99u32.to_le_bytes());assert!(target_range(&b,198,40).is_err());assert!(target_range(&b,5000,101).is_err());}
#[test]fn original_car_header_varint_is_bounded_and_canonical(){assert_eq!(varint(&[1]).unwrap(),(1,1));assert_eq!(varint(&[0x80,8]).unwrap(),(1024,2));for b in [&[0][..],&[0x81,0][..],&[0x80][..],&[0x81,8][..],&[0xff;10][..]]{assert!(varint(b).is_err());}}
#[test]fn plan_cannot_add_url_or_select_another_epoch(){assert!(exact_keys(&json!({"schema":0,"output_directory":0,"current_funding":0}),&["schema","output_directory","current_funding"]).is_ok());assert!(exact_keys(&json!({"schema":0,"output_directory":0,"current_funding":0,"url":"foreign"}),&["schema","output_directory","current_funding"]).is_err());}
#[test]fn expired_or_renewable_clock_is_not_accepted(){assert!(clock(&json!({"not_before_unix_millis":0,"deadline_unix_millis":30000})).is_err());let n=now().unwrap();assert!(clock(&json!({"not_before_unix_millis":n,"deadline_unix_millis":n+900001})).is_err());assert!(clock(&json!({"not_before_unix_millis":n+1000,"deadline_unix_millis":n+31000})).is_err());}
#[test]fn monotonic_deadline_cannot_be_extended_by_wall_clock(){let d=Deadline{unix_millis:now().unwrap()+60000,monotonic:Instant::now()};assert!(d.check().is_err());assert!(remaining(d).is_err());}
#[test]fn header_metadata_cannot_grow_without_bound(){let mut h=HeaderMap::new();h.insert("x-large",reqwest::header::HeaderValue::from_bytes(&vec![b'x';MAX_HEADERS+1]).unwrap());assert!(headers(&h).is_err());}
